  (* =================================================================== *)
  (* §3 Where the catalog comes from.                                      *)
  (* =================================================================== *)

  (* [seccomp_code] is defined above, at the top of the section, because
     every per-pc lemma consumes it. This is its INTRODUCTION, and the ONE
     place in the whole development where the program's bytes meet the
     process image: the entry hands out [utext_all gt M pm] -- the text half
     of the heap, over the image the kernel actually loaded -- and the two
     section hypotheses say that image contains the dump ([seccomp_text_sub])
     and that the executable segment is X-and-not-W ([Hx]), which is what
     puts those bytes in the TEXT half rather than the data one. Both are
     discharged HERE, once, instead of in each of the 351 per-pc lemmas. *)

  (* AND THE READ-ONLY IMAGE BESIDE IT. A program's string LITERALS are not
     in [SeccompInstrs.seccomp_bytes] and they are not in the data half
     either: .rodata shares the EXECUTABLE segment's pages, so its bytes are
     X-and-not-W and the heap files them under [γt] exactly as it files the
     code. This program's literals land at 0x94e..0xe5c, inside the R-X
     segment, and a printf-family walk LOADS them one byte at a time. This is
     the part of [SeccompData.seccomp_data] that lands there -- everything
     below the end of the executable segment -- and
     [UserHeap.utext_str_of_img] cuts a literal out of it at a concrete base
     and length. *)
  Definition seccomp_ro : gmap Z (bv 8) :=
    filter (fun kv => (kv.1 < 4096)%Z) SeccompData.seccomp_data.

  Definition seccomp_rodata (g : gname) : iProp Σ := utext_img g seccomp_ro.

  Global Instance seccomp_rodata_persistent g : Persistent (seccomp_rodata g).
  Proof using . apply _. Qed.

  Global Typeclasses Opaque seccomp_rodata.

  Lemma seccomp_rodata_of_text : utext_all gt M pm -∗ seccomp_rodata gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               seccomp_ro !! a = Some b -> M !! a = Some b).
    { intros a b Hb. apply map_lookup_filter_Some in Hb as [Hb _].
      exact (Hsub2 a b Hb). }
    assert (Hp : forall a : Z, is_Some (seccomp_ro !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply map_lookup_filter_Some in Hb as [Hb Hlt].
      apply Hx.
      pose proof (seccomp_data_key_nonneg a b Hb) as Hge.
      simpl in Hlt. lia. }
    iIntros "#Ht". rewrite /seccomp_rodata.
    iApply (utext_img_of_all gt M pm seccomp_ro Hin Hp with "Ht").
  Qed.

  Lemma seccomp_code_of_text : utext_all gt M pm -∗ seccomp_code gt.
  Proof.
    assert (Hin : forall (a : Z) (b : bv 8),
               SeccompInstrs.seccomp_bytes !! a = Some b -> M !! a = Some b)
      by exact Hsub.
    assert (Hp : forall a : Z, is_Some (SeccompInstrs.seccomp_bytes !! a) ->
                   ux_addr pm a /\ ~ uw_addr pm a).
    { intros a [b Hb]. apply Hx.
      pose proof (seccomp_bytes_key_lt a b Hb) as Hlt.
      pose proof (seccomp_bytes_key_nonneg a b Hb) as Hge. lia. }
    iIntros "#Ht". rewrite /seccomp_code.
    iApply (utext_img_of_all gt M pm SeccompInstrs.seccomp_bytes Hin Hp with "Ht").
  Qed.

End UCodeSeccomp.
